SELECT b.bill_no, b.bill_date, b.total_amount, b.remarks AS bill_remarks, i.item_name, i.qty, i.rate, i.amount AS item_amount, p.pay_date, p.paid_amount, p.remarks AS payment_remarks FROM rrsv_vendor_bills b LEFT JOIN rrsv_vendor_bill_items i ON b.id = i.bill_id LEFT JOIN rrsv_vendor_bill_payments p ON b.id = p.bill_id WHERE b.bill_no = 'VB928';


SELECT b.id AS bill_id, b.bill_no, b.bill_date, b.total_amount, b.remarks AS bill_remarks, i.item_name, i.qty, i.rate, i.amount AS item_amount, p.pay_date, p.paid_amount, p.remarks AS payment_remarks, e.id AS expense_id, e.expence_name, e.d_o_e AS expense_date, e.amount AS expense_amount, e.exp_desc, e.image FROM rrsv_vendor_bills b LEFT JOIN rrsv_vendor_bill_items i ON b.id = i.bill_id LEFT JOIN rrsv_vendor_bill_payments p ON b.id = p.bill_id LEFT JOIN rrsv_expence e ON e.from_no = REPLACE(b.bill_no, 'VB', '') WHERE b.bill_no = 'VB928';


SELECT b.id AS bill_id, b.bill_no, b.bill_date, b.total_amount, b.remarks AS bill_remarks, i.item_name, i.qty, i.rate, i.amount AS item_amount, p.pay_date, p.paid_amount, p.remarks AS payment_remarks, e.id AS expense_id, e.expence_name, e.d_o_e AS expense_date, e.amount AS expense_amount, e.exp_desc, pl.pl_date AS when_paid, pl.exp_amount AS pl_exp_amount,pl.purpose FROM rrsv_vendor_bills b LEFT JOIN rrsv_vendor_bill_items i ON b.id = i.bill_id LEFT JOIN rrsv_vendor_bill_payments p ON b.id = p.bill_id LEFT JOIN rrsv_expence e ON e.from_no = REPLACE(b.bill_no, 'VB', '') LEFT JOIN rrsv_scl_pl pl ON pl.bill = b.bill_no WHERE b.bill_no = 'VB928';


SELECT b.id AS bill_id, b.bill_no, b.bill_date, b.total_amount, b.remarks AS bill_remarks, i.total_item_amount, p.pay_date, p.paid_amount, p.remarks AS payment_remarks, e.total_expense, pl.total_pl_expense FROM rrsv_vendor_bills b LEFT JOIN ( SELECT bill_id, SUM(amount) AS total_item_amount FROM rrsv_vendor_bill_items GROUP BY bill_id ) i ON b.id = i.bill_id LEFT JOIN rrsv_vendor_bill_payments p ON b.id = p.bill_id -- keep payment rows separate LEFT JOIN ( SELECT from_no, SUM(amount) AS total_expense FROM rrsv_expence GROUP BY from_no ) e ON e.from_no = REPLACE(b.bill_no, 'VB', '') LEFT JOIN ( SELECT bill, SUM(exp_amount) AS total_pl_expense FROM rrsv_scl_pl GROUP BY bill ) pl ON pl.bill = b.bill_no WHERE b.bill_no = 'VB928';